class ArchitectureGovernanceEngineTest {@Test void detectsForbiddenDependencyAndDeprecatedTechnology(){var a=new QirNode("ui","service","ui","react",Map.of());var b=new QirNode("db","database","db","mysql",Map.of());var m=new QirModel("r","main",List.of(a,b),List.of(new QirEdge("ui","db","depends_on",Map.of("reason","explicit"))),List.of());var p=new PolicyPack("1",List.of(new ArchitecturePolicy("layers","no UI to DB","high",new ArchitecturePolicy.Rule("forbidden-dependency","service","database","depends_on",List.of(),null,null)),new ArchitecturePolicy("mysql-old","deprecated","medium",new ArchitecturePolicy.Rule("deprecated-technologies",null,null,null,List.of("mysql"),null,null))));var v=new ArchitectureGovernanceEngine().evaluate(m,p);assertEquals(2,v.size());}}